package com.abhiai.abhiai_backend.controller;
import java.util.UUID;import org.springframework.data.domain.Pageable;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.abhiai.abhiai_backend.dto.common.PageResponse;import com.abhiai.abhiai_backend.dto.follow.FollowRequestResponse;import com.abhiai.abhiai_backend.security.JwtPrincipal;import com.abhiai.abhiai_backend.service.FollowRequestService;
@RestController @RequestMapping("/api/v1/follow-requests") public class FollowRequestController{private final FollowRequestService s;public FollowRequestController(FollowRequestService s){this.s=s;}@PostMapping("/{userId}") public ResponseEntity<FollowRequestResponse> request(@AuthenticationPrincipal JwtPrincipal p,@PathVariable UUID userId){return ResponseEntity.status(201).body(s.request(p.userId(),userId));}@GetMapping public PageResponse<FollowRequestResponse> inbox(@AuthenticationPrincipal JwtPrincipal p,Pageable page){return s.inbox(p.userId(),page);}@PostMapping("/{id}/accept")@ResponseStatus(HttpStatus.NO_CONTENT)public void accept(@AuthenticationPrincipal JwtPrincipal p,@PathVariable UUID id){s.decide(p.userId(),id,true);}@PostMapping("/{id}/reject")@ResponseStatus(HttpStatus.NO_CONTENT)public void reject(@AuthenticationPrincipal JwtPrincipal p,@PathVariable UUID id){s.decide(p.userId(),id,false);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void cancel(@AuthenticationPrincipal JwtPrincipal p,@PathVariable UUID id){s.cancel(p.userId(),id);}}
